package com.orderflow.notification.correlation;import com.orderflow.platform.http.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import org.slf4j.MDC;import org.springframework.core.*;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;@Component @Order(Ordered.HIGHEST_PRECEDENCE)public class CorrelationIdFilter extends OncePerRequestFilter{protected void doFilterInternal(HttpServletRequest q,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String id=CorrelationIdValidator.validateOrGenerate(q.getHeader(CorrelationHeaders.CORRELATION_ID));q.setAttribute(NotificationRequestAttributes.CORRELATION_ID,id);p.setHeader(CorrelationHeaders.CORRELATION_ID,id);MDC.put("correlationId",id);try{c.doFilter(q,p);}finally{MDC.remove("correlationId");}}}
